import{_ as o,o as c,c as d,a2 as _}from"./chunks/framework.D7EuCHIT.js";const i=JSON.parse('{"title":"宿主网络、存储与拦截","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/host-services.md","filePath":"plugins/host-services.md","lastUpdated":1795358384000}'),E={name:"plugins/host-services.md"};function T(a,e,t,R,A,r){return c(),d("div",null,[...e[0]||(e[0]=[_('<h1 id="宿主网络、存储与拦截" tabindex="-1">宿主网络、存储与拦截 <a class="header-anchor" href="#宿主网络、存储与拦截" aria-label="Permalink to &quot;宿主网络、存储与拦截&quot;">​</a></h1><p>宿主为插件提供三个消息接口：<code>LYRA_INTERFACE_NET</code>（32，<code>plugin/net_contracts.h</code>）、<code>LYRA_INTERFACE_STORE</code>（33，<code>plugin/store_contracts.h</code>）、<code>LYRA_INTERFACE_SERVICE_TAP</code>（34，<code>plugin/tap_contracts.h</code>）。它们与 <code>system.net</code>、<code>system.store</code> 内置服务走同一注册表路径，可被同名能力的插件整体替换。</p><p>所有调用都在宿主帧线程、有效 Activity 生命周期内进行；请求字符串只在调用期间借用，需要保存时先复制。</p><h2 id="异步-http-lyra-interface-net" tabindex="-1">异步 HTTP：LYRA_INTERFACE_NET <a class="header-anchor" href="#异步-http-lyra-interface-net" aria-label="Permalink to &quot;异步 HTTP：LYRA_INTERFACE_NET&quot;">​</a></h2><p>操作：<code>LYRA_NET_REQUEST</code>(1)、<code>LYRA_NET_POLL</code>(2)、<code>LYRA_NET_CANCEL</code>(3)、<code>LYRA_NET_INBOUND</code>(4)、<code>LYRA_NET_LISTEN_OPEN</code>(5)、<code>LYRA_NET_LISTEN_POLL</code>(6)、<code>LYRA_NET_LISTEN_ANSWER</code>(7)、<code>LYRA_NET_LISTEN_CLOSE</code>(8)。</p><p>REQUEST 字段：<code>LYRA_NET_METHOD</code>（GET/POST 等）、<code>LYRA_NET_URL</code>、可选 <code>LYRA_NET_HEADERS</code>（JSON 对象）、<code>LYRA_NET_BODY</code>（二进制）、<code>LYRA_NET_MAX_BYTES</code>、<code>LYRA_NET_TIMEOUT_MS</code>。返回 <code>LYRA_NET_JOB</code> 句柄；POLL 返回 <code>LYRA_NET_STATE</code>/<code>LYRA_NET_STATUS</code>/<code>LYRA_NET_FD</code>（响应体 fd，调用方负责关闭）与可选 <code>LYRA_NET_RESPONSE_HEADERS</code>/<code>LYRA_NET_RESPONSE_BODY</code>；CANCEL 释放任务。响应体有 <code>max_bytes</code> 上限，超时按读操作计。</p><p>重定向最多跟随 6 次；跨源不携带 Authorization/Cookie 等请求头；仅 HTTPS，HTTP 明文与 userinfo URL 被拒绝。</p><h2 id="登录闭环-深链与回环监听" tabindex="-1">登录闭环：深链与回环监听 <a class="header-anchor" href="#登录闭环-深链与回环监听" aria-label="Permalink to &quot;登录闭环：深链与回环监听&quot;">​</a></h2><ul><li><strong>深链投递</strong>：宿主接受 <code>lyra://plugin/&lt;插件id&gt;/&lt;路径&gt;</code> 链接，按插件 id 入队。插件用 <code>LYRA_NET_INBOUND</code> 轮询取回投递给自己的链接（<code>LYRA_NET_LINKS</code>）。</li><li><strong>回环监听</strong>：<code>LYRA_NET_LISTEN_OPEN</code> 在 <code>127.0.0.1</code> 开监听（可指定 <code>LYRA_NET_PORT</code> 与 <code>LYRA_NET_PREFIX</code> 路径前缀），<code>LYRA_NET_LISTEN_POLL</code> 取回请求（<code>LYRA_NET_REQUEST_ID</code> + 原始报文 fd），插件处理后用 <code>LYRA_NET_LISTEN_ANSWER</code> 回 <code>LYRA_NET_RESPONSE_STATUS</code>/<code>LYRA_NET_RESPONSE_HEADERS</code>/<code>LYRA_NET_RESPONSE_BODY</code>，最后 <code>LYRA_NET_LISTEN_CLOSE</code> 关闭。适合 OAuth 回调、扫码登录、本地 SSO。</li></ul><h2 id="插件存储-lyra-interface-store" tabindex="-1">插件存储：LYRA_INTERFACE_STORE <a class="header-anchor" href="#插件存储-lyra-interface-store" aria-label="Permalink to &quot;插件存储：LYRA_INTERFACE_STORE&quot;">​</a></h2><p>操作：<code>LYRA_STORE_GET</code>(1)、<code>LYRA_STORE_SET</code>(2)、<code>LYRA_STORE_DELETE</code>(3)、<code>LYRA_STORE_KEYS</code>(4)。字段：<code>LYRA_STORE_KEY</code>、<code>LYRA_STORE_VALUE</code>、<code>LYRA_STORE_SECRET</code>（SET 时置位走加密存储）、<code>LYRA_STORE_KEYS_OUT</code>、<code>LYRA_STORE_FOUND</code>。</p><p>命名空间由宿主按<strong>调用者身份</strong>隔离：插件只能读写自己的键，无法伪造 owner 访问他人数据。单值上限 1 MiB。<code>SECRET</code> 置位的值经 Android Keystore 包裹的 AES-256-GCM 加密落盘，明文不出现在 SharedPreferences；适合 token、凭据等秘密。普通配置仍应走 <code>CONFIG_SCHEMA</code> 声明的配置表。</p><h2 id="服务拦截-lyra-interface-service-tap" tabindex="-1">服务拦截：LYRA_INTERFACE_SERVICE_TAP <a class="header-anchor" href="#服务拦截-lyra-interface-service-tap" aria-label="Permalink to &quot;服务拦截：LYRA_INTERFACE_SERVICE_TAP&quot;">​</a></h2><p>任何选中服务可在 <code>query_interface</code> 暴露 <code>LyraServiceTapV3</code>。宿主在每次消息传输的服务请求前按注册顺序调用 tap，tap 看到原 <code>LyraMessageV3</code> 及尾部元数据字段 <code>LYRA_TAP_META_HANDLE</code>（目标服务句柄）、<code>LYRA_TAP_META_INTERFACE</code>（请求接口 ID）。</p><p>通过 reply 返回：</p><ul><li><code>LYRA_TAP_PASS</code>(0)：透传给目标服务；</li><li><code>LYRA_TAP_REWRITE</code>(1)：reply-&gt;fields 替换字段集，可选 <code>LYRA_TAP_META_OPERATION</code>（i64）改写操作码；</li><li><code>LYRA_TAP_ANSWER</code>(2)：reply 直接作为结果返回给原调用方，目标服务不再执行。</li></ul><p>嵌套深度受限；无效动作按透传处理。适用于聚合搜索、改写参数、审计等横切关注点，不需要按能力名分支。</p><h2 id="替换与兼容" tabindex="-1">替换与兼容 <a class="header-anchor" href="#替换与兼容" aria-label="Permalink to &quot;替换与兼容&quot;">​</a></h2><p><code>system.net</code>/<code>system.store</code> 可用同名 capability 发布替代实现；旧宿主不支持这些接口时 <code>query_interface</code> 返回 NULL，插件应回退到自带传输或禁用相关功能。</p>',19)])])}const N=o(E,[["render",T]]);export{i as __pageData,N as default};
